foreach(['project'=>$ts,'standalone'=>$singlePriority]as$kind=>$writer)foreach([$a,$b,$primary]as$owner){
 $id=$makeTimerTask($writer,$kind,$owner,'positive');$request=$key('timer-start-'.$kind.'-'.$owner);$writer->activity($owner,7,$id,1,'start',$request);$r=$writer->get($owner,7,$id);$expected=$owner===$b?'todo':'in_progress';essentialCheck($r['status']===$expected&&(int)$r['revision']===2&&count($r['timers'])===1&&$r['timers'][0]['stopped_at']===null,'same canonical start applies only current owner policy '.$kind.'/'.$owner);
