 if($owner===$a){$foreign=$makeTimerTask($writer,$kind,$b,'blocked-foreign');essentialThrows(fn()=>$writer->activity($b,7,$foreign,1,'start',$key('timer-cross-'.$kind)),'company_project_timer_running','running timer in A blocks B without stopping or changing either company');essentialCheck($writer->get($b,7,$foreign)['status']==='todo'&&$writer->get($b,7,$foreign)['timers']===[],'cross-company refusal creates no timer or status effect');}
