function timerTransitionState($db,string$p):array{$out=[];foreach(['issuers_registry','issuers_resource_permissions','staff','company_tasks','company_standalone_tasks','company_task_timers','company_standalone_timers','company_task_priorities','company_standalone_priorities','company_task_followers','company_project_requests','issuers_audit','options']as$t){$rows=array_map('serialize',$db->query('SELECT * FROM '.$p.$t)->result_array());sort($rows,SORT_STRING);$out[$t]=$rows;}return$out;}
foreach(['project'=>$ts,'standalone'=>$singlePriority]as$kind=>$writer){$table=$kind==='project'?'company_tasks':'company_standalone_tasks';$event=$kind==='project'?'company_task_start':'company_standalone_task_start';
 foreach(['settings','row','timer','actor','grant']as$fault){$faultActor=$fault==='grant'?12:7;$db->query('UPDATE '.$p.'issuers_staff SET can_view=1 WHERE issuer_id=? AND staff_id=12',[$b]);if(!$db->query("SELECT staff_id FROM {$p}issuers_resource_permissions WHERE issuer_id=? AND staff_id=12 AND feature='tasks' AND capability='edit'",[$b])->row_array())$db->query("INSERT INTO {$p}issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(?,12,'tasks','edit')",[$b]);$id=$makeTimerTask($writer,$kind,$b,'late-'.$fault);$request=$key('timer-late-'.$kind.'-'.$fault);$before=timerTransitionState($db,$p);$mutation=match($fault){'settings'=>"UPDATE {$p}issuers_registry SET settings_json='{}' WHERE id=$b",'row'=>"UPDATE {$p}$table SET status='todo' WHERE issuer_id=$b AND id=$id",'timer'=>"UPDATE {$p}".($kind==='project'?'company_task_timers':'company_standalone_timers')." SET seconds=1 WHERE issuer_id=$b AND task_id=$id",'actor'=>"UPDATE {$p}staff SET active=0 WHERE staffid=7",'grant'=>"DELETE FROM {$p}issuers_resource_permissions WHERE issuer_id=$b AND staff_id=$faultActor AND feature='tasks' AND capability='edit'"};
  $sql=$db->driver()==='mysql'?"CREATE TRIGGER {$p}timer_transition_fault AFTER INSERT ON {$p}issuers_audit FOR EACH ROW BEGIN IF NEW.event='$event' THEN $mutation; END IF; END":"CREATE TRIGGER {$p}timer_transition_fault AFTER INSERT ON {$p}issuers_audit WHEN NEW.event='$event' BEGIN $mutation; END";$db->query($sql);$caught=null;try{$writer->activity($b,$faultActor,$id,1,'start',$request);}catch(Throwable$e){$caught=$e->getMessage();}finally{$db->query('DROP TRIGGER '.$p.'timer_transition_fault');}
  essentialCheck(in_array($caught,['issuer_task_timer_unconfirmed','issuer_project_write_unconfirmed','company_project_access_denied','company_project_reference_denied'],true),'real final-audit '.$kind.'/'.$fault.' blocks start: '.var_export($caught,true));essentialCheck(timerTransitionState($db,$p)===$before,'final-audit '.$kind.'/'.$fault.' rolls back timer/status/receipt/policy/grants exactly');$writer->activity($b,$faultActor,$id,1,'start',$request);$r=$writer->get($b,7,$id);essentialCheck($r['status']==='in_progress'&&count($r['timers'])===1,'same failed key retries exactly one start after removing real fault');$writer->activity($b,$faultActor,$id,2,'stop',$key('timer-late-stop-'.$kind.'-'.$fault));
 }
}
